"""HTTP entry point for PowerRail."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .service import ApiError, Service

SOC_ROUTE = "/v1/battery/soc/estimate"
HEALTH_ROUTE = "/v1/battery/health/estimate"
POWER_BUDGET_ROUTE = "/v1/power/budget/allocate"
TELEMETRY_FILTER_ROUTE = "/v1/telemetry/filter"


def env_address() -> tuple[str, int]:
    raw = os.environ.get("POWERRAIL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid POWERRAIL_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path not in (SOC_ROUTE, HEALTH_ROUTE, POWER_BUDGET_ROUTE, TELEMETRY_FILTER_ROUTE):
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw.decode("utf-8")) if raw else None
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_json(
                400, {"error": {"code": "invalid_json", "message": "request body must be valid JSON"}}
            )
            return
        try:
            if self.path == SOC_ROUTE:
                result = self.service.estimate_soc(payload)
            elif self.path == HEALTH_ROUTE:
                result = self.service.estimate_health(payload)
            elif self.path == POWER_BUDGET_ROUTE:
                result = self.service.allocate_power_budget(payload)
            else:
                result = self.service.filter_telemetry(payload)
        except ApiError as exc:
            self.send_json(
                exc.status, {"error": {"code": exc.code, "message": exc.message}}
            )
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="powerrail.server", description="电源与能耗管理平台")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"PowerRail listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Core service surface for PowerRail.

The baseline reports process health; battery state-of-charge estimation is
served from :meth:`Service.estimate_soc`. Keep the public surface here
backward compatible and express all client failures as :class:`ApiError`.
"""

from __future__ import annotations

import math
from typing import Any

from . import __version__

DEFAULT_REST_CURRENT_A = 0.05
DEFAULT_REST_DURATION_S = 300.0
DEFAULT_OCV_WEIGHT = 0.2
DEFAULT_END_OF_LIFE_SOH = 0.8
DEFAULT_MEDIAN_WINDOW = 3
DEFAULT_SMOOTHING_FACTOR = 0.25
DEFAULT_RESET_GAP_S = 30.0


class ApiError(Exception):
    """Client error carrying an HTTP status and a stable machine-readable code."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _is_finite_number(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` but is not a valid numeric reading.
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


def _median(values: list[float]) -> float:
    """Median of a non-empty list; even counts average the middle pair."""
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def _interpolate_ocv(voltage: float, points: list[tuple[float, float]]) -> float:
    """Linearly interpolate SoC from a voltage-sorted OCV curve.

    Voltages outside the curve resolve to the nearest endpoint.
    """
    first_voltage, first_soc = points[0]
    last_voltage, last_soc = points[-1]
    if voltage <= first_voltage:
        return first_soc
    if voltage >= last_voltage:
        return last_soc
    for (v0, s0), (v1, s1) in zip(points, points[1:]):
        if voltage <= v1:
            ratio = (voltage - v0) / (v1 - v0)
            return s0 + ratio * (s1 - s0)
    return last_soc  # pragma: no cover - unreachable for a sorted curve


class Service:
    """Stateless service surface: health reporting and SoC estimation."""

    name = "powerrail"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def estimate_soc(self, payload: Any) -> dict[str, Any]:
        """Validate and run a coulomb-counting SoC estimate with OCV correction."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        capacity = payload.get("capacity_ah")
        if not _is_finite_number(capacity) or capacity <= 0:
            raise ApiError(
                422, "invalid_capacity", "capacity_ah must be a positive finite number"
            )

        initial_soc = payload.get("initial_soc")
        if not _is_finite_number(initial_soc) or not 0 <= initial_soc <= 1:
            raise ApiError(
                422,
                "invalid_initial_soc",
                "initial_soc must be a finite number within [0, 1]",
            )

        samples = payload.get("samples")
        if not isinstance(samples, list) or not samples:
            raise ApiError(422, "invalid_samples", "samples must be a non-empty array")

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for sample in samples:
            if not isinstance(sample, dict):
                raise ApiError(
                    422,
                    "invalid_timestamp",
                    "each sample must be an object with a finite timestamp_s",
                )
            timestamp = sample.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(timestamp)
            previous_timestamp = timestamp

        currents: list[float] = []
        voltages: list[float] = []
        for sample in samples:
            current = sample.get("current_a")
            voltage = sample.get("voltage_v")
            if not _is_finite_number(current) or not _is_finite_number(voltage):
                raise ApiError(
                    422,
                    "invalid_measurement",
                    "current_a and voltage_v must be finite numbers",
                )
            currents.append(current)
            voltages.append(voltage)

        ocv_points = self._parse_ocv_curve(payload.get("ocv_curve"))
        rest_current, rest_duration, ocv_weight = self._parse_options(payload)

        estimates: list[dict[str, Any]] = []
        soc = initial_soc
        rest_elapsed = 0.0
        capacity_seconds = capacity * 3600.0

        for index in range(len(samples)):
            timestamp = timestamps[index]
            if index == 0:
                estimates.append(
                    {"timestamp_s": timestamp, "soc": soc, "source": "coulomb"}
                )
                continue

            delta_time = timestamp - timestamps[index - 1]
            average_current = (currents[index - 1] + currents[index]) / 2.0
            soc_next = soc - average_current * delta_time / capacity_seconds
            if soc_next < 0.0:
                soc_next = 0.0
            elif soc_next > 1.0:
                soc_next = 1.0

            source = "coulomb"
            if ocv_points is not None:
                if (
                    abs(currents[index - 1]) <= rest_current
                    and abs(currents[index]) <= rest_current
                ):
                    rest_elapsed += delta_time
                else:
                    rest_elapsed = 0.0
                if rest_elapsed >= rest_duration:
                    ocv_soc = _interpolate_ocv(voltages[index], ocv_points)
                    soc_next = (
                        1.0 - ocv_weight
                    ) * soc_next + ocv_weight * ocv_soc
                    source = "ocv_corrected"

            soc = soc_next
            estimates.append(
                {"timestamp_s": timestamp, "soc": soc, "source": source}
            )

        return {"estimates": estimates, "final_soc": soc}

    def estimate_health(self, payload: Any) -> dict[str, Any]:
        """Estimate battery state of health and remaining cycle life."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        nominal_capacity = payload.get("nominal_capacity_ah")
        if not _is_finite_number(nominal_capacity) or nominal_capacity <= 0:
            raise ApiError(
                422,
                "invalid_nominal_capacity",
                "nominal_capacity_ah must be a positive finite number",
            )

        measurements = payload.get("measurements")
        if not isinstance(measurements, list) or len(measurements) < 2:
            raise ApiError(
                422,
                "invalid_measurements",
                "measurements must be an array with at least two items",
            )
        for measurement in measurements:
            if not isinstance(measurement, dict):
                raise ApiError(
                    422,
                    "invalid_measurements",
                    "each measurement must be an object",
                )

        end_of_life_soh = payload.get("end_of_life_soh", DEFAULT_END_OF_LIFE_SOH)
        if (
            not _is_finite_number(end_of_life_soh)
            or not 0 <= end_of_life_soh <= 1
        ):
            raise ApiError(
                422,
                "invalid_end_of_life_soh",
                "end_of_life_soh must be a finite number within [0, 1]",
            )

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for measurement in measurements:
            timestamp = measurement.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(timestamp)
            previous_timestamp = timestamp

        measured_capacities: list[float] = []
        for measurement in measurements:
            measured_capacity = measurement.get("measured_capacity_ah")
            if not _is_finite_number(measured_capacity) or measured_capacity <= 0:
                raise ApiError(
                    422,
                    "invalid_capacity_measurement",
                    "measured_capacity_ah must be a positive finite number",
                )
            measured_capacities.append(measured_capacity)

        cumulative_discharge: list[float] = []
        previous_throughput: float | None = None
        for measurement in measurements:
            throughput = measurement.get("cumulative_discharge_ah")
            if not _is_finite_number(throughput) or throughput < 0:
                raise ApiError(
                    422,
                    "invalid_throughput",
                    "cumulative_discharge_ah must be a non-negative finite number",
                )
            if previous_throughput is not None and throughput < previous_throughput:
                raise ApiError(
                    422,
                    "invalid_throughput",
                    "cumulative_discharge_ah must be non-decreasing",
                )
            cumulative_discharge.append(throughput)
            previous_throughput = throughput

        estimates: list[dict[str, Any]] = []
        for index in range(len(measurements)):
            soh = measured_capacities[index] / nominal_capacity
            if soh < 0.0:
                soh = 0.0
            elif soh > 1.0:
                soh = 1.0
            equivalent_cycles = cumulative_discharge[index] / nominal_capacity
            estimates.append(
                {
                    "timestamp_s": timestamps[index],
                    "soh": soh,
                    "equivalent_cycles": equivalent_cycles,
                }
            )

        latest_soh = estimates[-1]["soh"]
        consumed_cycles = estimates[-1]["equivalent_cycles"]

        remaining_cycles: float | None
        if latest_soh <= end_of_life_soh:
            remaining_cycles = 0
            projection_status = "end_of_life"
        else:
            first_soh = estimates[0]["soh"]
            first_cycles = estimates[0]["equivalent_cycles"]
            cycle_span = consumed_cycles - first_cycles
            soh_drop = first_soh - latest_soh
            if cycle_span > 0 and soh_drop > 0:
                degradation_rate = soh_drop / cycle_span
                remaining_cycles = (latest_soh - end_of_life_soh) / degradation_rate
                projection_status = "projected"
            else:
                remaining_cycles = None
                projection_status = "insufficient_trend"

        return {
            "estimates": estimates,
            "latest_soh": latest_soh,
            "consumed_cycles": consumed_cycles,
            "remaining_cycles": remaining_cycles,
            "projection_status": projection_status,
        }

    def allocate_power_budget(self, payload: Any) -> dict[str, Any]:
        """Allocate a power budget across prioritized loads.

        Minimum power is funded first, highest priority level first; a
        level that cannot be fully funded splits the remainder
        proportionally to each load's minimum and lower levels get
        nothing. Leftover power then funds unmet demand the same way.
        """
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        available = payload.get("available_power_w")
        if not _is_finite_number(available) or available < 0:
            raise ApiError(
                422,
                "invalid_budget",
                "available_power_w must be a non-negative finite number",
            )

        reserve = payload.get("reserve_power_w", 0.0)
        if not _is_finite_number(reserve) or reserve < 0:
            raise ApiError(
                422,
                "invalid_budget",
                "reserve_power_w must be a non-negative finite number",
            )
        if reserve > available:
            raise ApiError(
                422,
                "invalid_budget",
                "reserve_power_w must not exceed available_power_w",
            )

        loads = payload.get("loads")
        if not isinstance(loads, list) or not loads:
            raise ApiError(422, "invalid_loads", "loads must be a non-empty array")
        for load in loads:
            if not isinstance(load, dict):
                raise ApiError(422, "invalid_loads", "each load must be an object")

        ids: list[str] = []
        demands: list[float] = []
        minimums: list[float] = []
        priorities: list[int] = []
        seen_ids: set[str] = set()
        for load in loads:
            load_id = load.get("id")
            if not isinstance(load_id, str) or not load_id:
                raise ApiError(
                    422, "invalid_load_id", "each load id must be a non-empty string"
                )
            if load_id in seen_ids:
                raise ApiError(
                    422, "invalid_load_id", f"load id {load_id!r} is duplicated"
                )
            seen_ids.add(load_id)
            ids.append(load_id)

            demand = load.get("demand_power_w")
            minimum = load.get("min_power_w")
            if not _is_finite_number(demand) or demand < 0:
                raise ApiError(
                    422,
                    "invalid_load_power",
                    "demand_power_w must be a non-negative finite number",
                )
            if not _is_finite_number(minimum) or minimum < 0:
                raise ApiError(
                    422,
                    "invalid_load_power",
                    "min_power_w must be a non-negative finite number",
                )
            if minimum > demand:
                raise ApiError(
                    422,
                    "invalid_load_power",
                    "min_power_w must not exceed demand_power_w",
                )
            demands.append(float(demand))
            minimums.append(float(minimum))

            priority = load.get("priority")
            if (
                not isinstance(priority, int)
                or isinstance(priority, bool)
                or not 0 <= priority <= 100
            ):
                raise ApiError(
                    422,
                    "invalid_priority",
                    "priority must be an integer within [0, 100]",
                )
            priorities.append(priority)

        distributable = available - reserve
        allocated = [0.0] * len(loads)
        remaining = self._fund_levels(minimums, priorities, ids, allocated, distributable)
        remaining = self._fund_levels(demands, priorities, ids, allocated, remaining)

        # Keep floating-point drift inside the documented invariants.
        for index in range(len(loads)):
            if allocated[index] < 0.0:
                allocated[index] = 0.0
            elif allocated[index] > demands[index]:
                allocated[index] = demands[index]
        excess = sum(allocated) - distributable
        if excess > 0.0:
            for index in sorted(range(len(loads)), key=lambda i: (-allocated[i], ids[i])):
                if excess <= 0.0:
                    break
                cut = min(allocated[index], excess)
                allocated[index] -= cut
                excess -= cut
        total_allocated = sum(allocated)
        unallocated = distributable - total_allocated
        if unallocated < 0.0:
            unallocated = 0.0

        allocations: list[dict[str, Any]] = []
        satisfied = True
        for index in range(len(loads)):
            shortfall = demands[index] - allocated[index]
            if shortfall < 0.0:
                shortfall = 0.0
            if demands[index] == 0.0 or allocated[index] >= demands[index]:
                state = "powered"
            elif allocated[index] > 0.0:
                state = "limited"
                satisfied = False
            else:
                state = "shed"
                satisfied = False
            allocations.append(
                {
                    "id": ids[index],
                    "allocated_power_w": allocated[index],
                    "shortfall_power_w": shortfall,
                    "state": state,
                }
            )

        return {
            "status": "satisfied" if satisfied else "constrained",
            "allocated_power_w": total_allocated,
            "unallocated_power_w": unallocated,
            "allocations": allocations,
        }

    def filter_telemetry(self, payload: Any) -> dict[str, Any]:
        """Denoise current/voltage telemetry with segment-aware median + EMA."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        samples = payload.get("samples")
        if not isinstance(samples, list) or not samples:
            raise ApiError(422, "invalid_samples", "samples must be a non-empty array")
        for sample in samples:
            if not isinstance(sample, dict):
                raise ApiError(422, "invalid_samples", "each sample must be an object")

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for sample in samples:
            timestamp = sample.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(float(timestamp))
            previous_timestamp = timestamp

        currents: list[float] = []
        voltages: list[float] = []
        for sample in samples:
            current = sample.get("current_a")
            voltage = sample.get("voltage_v")
            if not _is_finite_number(current) or not _is_finite_number(voltage):
                raise ApiError(
                    422,
                    "invalid_measurement",
                    "current_a and voltage_v must be finite numbers",
                )
            currents.append(float(current))
            voltages.append(float(voltage))

        median_window, smoothing_factor, reset_gap_s = self._parse_filter_options(
            payload
        )

        filtered_samples: list[dict[str, Any]] = []
        current_history: list[float] = []
        voltage_history: list[float] = []
        previous_current: float | None = None
        previous_voltage: float | None = None
        segment_count = 0

        for index in range(len(samples)):
            segment_start = False
            if index == 0 or timestamps[index] - timestamps[index - 1] > reset_gap_s:
                segment_count += 1
                segment_start = True
                current_history = []
                voltage_history = []
                previous_current = None
                previous_voltage = None

            current_median = _median(current_history + [currents[index]])
            voltage_median = _median(voltage_history + [voltages[index]])
            if previous_current is None:
                filtered_current = current_median
                filtered_voltage = voltage_median
            else:
                filtered_current = (
                    smoothing_factor * current_median
                    + (1.0 - smoothing_factor) * previous_current
                )
                filtered_voltage = (
                    smoothing_factor * voltage_median
                    + (1.0 - smoothing_factor) * previous_voltage
                )

            filtered_samples.append(
                {
                    "timestamp_s": samples[index]["timestamp_s"],
                    "filtered_current_a": filtered_current,
                    "filtered_voltage_v": filtered_voltage,
                    "segment_start": segment_start,
                }
            )

            previous_current = filtered_current
            previous_voltage = filtered_voltage
            current_history.append(currents[index])
            voltage_history.append(voltages[index])
            max_previous = median_window - 1
            if len(current_history) > max_previous:
                current_history = current_history[-max_previous:] if max_previous else []
                voltage_history = voltage_history[-max_previous:] if max_previous else []

        return {
            "samples": filtered_samples,
            "segment_count": segment_count,
            "sample_count": len(samples),
        }

    @staticmethod
    def _parse_filter_options(
        payload: dict[str, Any],
    ) -> tuple[int, float, float]:
        median_window = payload.get("median_window", DEFAULT_MEDIAN_WINDOW)
        if (
            not isinstance(median_window, int)
            or isinstance(median_window, bool)
            or not 1 <= median_window <= 11
            or median_window % 2 == 0
        ):
            raise ApiError(
                422,
                "invalid_filter_options",
                "median_window must be an odd integer within [1, 11]",
            )

        smoothing_factor = payload.get("smoothing_factor", DEFAULT_SMOOTHING_FACTOR)
        if not _is_finite_number(smoothing_factor) or not 0.0 < smoothing_factor <= 1.0:
            raise ApiError(
                422,
                "invalid_filter_options",
                "smoothing_factor must be a finite number within (0, 1]",
            )

        reset_gap_s = payload.get("reset_gap_s", DEFAULT_RESET_GAP_S)
        if not _is_finite_number(reset_gap_s) or reset_gap_s <= 0.0:
            raise ApiError(
                422,
                "invalid_filter_options",
                "reset_gap_s must be a positive finite number",
            )

        return median_window, float(smoothing_factor), float(reset_gap_s)

    @staticmethod
    def _fund_levels(
        targets: list[float],
        priorities: list[int],
        ids: list[str],
        allocated: list[float],
        remaining: float,
    ) -> float:
        """Fund loads toward ``targets`` by descending priority level.

        Fully funds each level while the remaining power covers the
        level's unmet need; otherwise splits the remainder across the
        level proportionally to unmet need and returns zero. Members are
        visited in id order so results do not depend on input ordering.
        """
        by_priority: dict[int, list[int]] = {}
        for index, priority in enumerate(priorities):
            by_priority.setdefault(priority, []).append(index)
        for priority in sorted(by_priority, reverse=True):
            if remaining <= 0.0:
                break
            members = [
                index
                for index in sorted(by_priority[priority], key=lambda i: ids[i])
                if targets[index] > allocated[index]
            ]
            if not members:
                continue
            needs = [targets[index] - allocated[index] for index in members]
            level_total = sum(needs)
            if level_total <= remaining:
                for index in members:
                    allocated[index] = targets[index]
                remaining -= level_total
            else:
                for index, need in zip(members, needs):
                    allocated[index] += remaining * need / level_total
                remaining = 0.0
                break
        return remaining

    @staticmethod
    def _parse_ocv_curve(
        curve: Any,
    ) -> list[tuple[float, float]] | None:
        if curve is None:
            return None
        if not isinstance(curve, list) or len(curve) < 2:
            raise ApiError(
                422, "invalid_ocv_curve", "ocv_curve must contain at least two points"
            )
        points: list[tuple[float, float]] = []
        previous_voltage: float | None = None
        previous_soc: float | None = None
        for point in curve:
            if not isinstance(point, dict):
                raise ApiError(
                    422, "invalid_ocv_curve", "each OCV point must be an object"
                )
            voltage = point.get("voltage_v")
            soc = point.get("soc")
            if not _is_finite_number(voltage) or not _is_finite_number(soc):
                raise ApiError(
                    422,
                    "invalid_ocv_curve",
                    "OCV point voltage_v and soc must be finite numbers",
                )
            if not 0 <= soc <= 1:
                raise ApiError(
                    422, "invalid_ocv_curve", "OCV point soc must be within [0, 1]"
                )
            if previous_voltage is not None:
                if voltage <= previous_voltage:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point voltage_v must be strictly increasing",
                    )
                if soc < previous_soc:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point soc must be non-decreasing",
                    )
            points.append((voltage, soc))
            previous_voltage = voltage
            previous_soc = soc
        return points

    @staticmethod
    def _parse_options(payload: dict[str, Any]) -> tuple[float, float, float]:
        rest_current = payload.get("rest_current_a", DEFAULT_REST_CURRENT_A)
        rest_duration = payload.get("rest_duration_s", DEFAULT_REST_DURATION_S)
        ocv_weight = payload.get("ocv_weight", DEFAULT_OCV_WEIGHT)
        if (
            not _is_finite_number(rest_current)
            or not _is_finite_number(rest_duration)
            or not _is_finite_number(ocv_weight)
        ):
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a, rest_duration_s and ocv_weight must be finite numbers",
            )
        if rest_current < 0 or rest_duration < 0 or not 0 <= ocv_weight <= 1:
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a and rest_duration_s must be non-negative and "
                "ocv_weight must be within [0, 1]",
            )
        return rest_current, rest_duration, ocv_weight

import json
import threading
import unittest
import urllib.error
import urllib.request
from http.server import ThreadingHTTPServer

from powerrail.server import POWER_BUDGET_ROUTE, Handler
from powerrail.service import ApiError, Service


def load(id_, demand, minimum, priority):
    return {
        "id": id_,
        "demand_power_w": demand,
        "min_power_w": minimum,
        "priority": priority,
    }


def base_request(**overrides):
    payload = {
        "available_power_w": 110.0,
        "loads": [load("a", 60.0, 10.0, 10), load("b", 50.0, 20.0, 5)],
    }
    payload.update(overrides)
    return payload


class PowerBudgetAllocationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def test_all_demands_satisfied(self) -> None:
        result = self.service.allocate_power_budget(base_request())
        self.assertEqual(result["status"], "satisfied")
        self.assertAlmostEqual(result["allocated_power_w"], 110.0)
        self.assertAlmostEqual(result["unallocated_power_w"], 0.0)
        states = {a["id"]: a["state"] for a in result["allocations"]}
        self.assertEqual(states, {"a": "powered", "b": "powered"})
        for item in result["allocations"]:
            self.assertAlmostEqual(item["shortfall_power_w"], 0.0)

    def test_allocations_follow_input_order(self) -> None:
        result = self.service.allocate_power_budget(base_request())
        self.assertEqual([a["id"] for a in result["allocations"]], ["a", "b"])

    def test_reserve_reduces_distributable_power(self) -> None:
        result = self.service.allocate_power_budget(
            base_request(available_power_w=100.0, reserve_power_w=40.0)
        )
        # 60 W distributable: mins 10 + 20 = 30, then 30 left for demand
        # top-up: a (priority 10) gets 50 - 10 = 40 -> capped by remaining.
        by_id = {a["id"]: a for a in result["allocations"]}
        self.assertAlmostEqual(by_id["a"]["allocated_power_w"], 40.0)
        self.assertAlmostEqual(by_id["b"]["allocated_power_w"], 20.0)
        self.assertEqual(by_id["a"]["state"], "limited")
        self.assertEqual(by_id["b"]["state"], "limited")
        self.assertEqual(result["status"], "constrained")
        self.assertAlmostEqual(result["allocated_power_w"], 60.0)
        self.assertAlmostEqual(result["unallocated_power_w"], 0.0)

    def test_minimums_funded_before_lower_priority_demand(self) -> None:
        # 35 W: high min 10 funded, low min 20 funded, 5 left for high demand.
        result = self.service.allocate_power_budget(
            base_request(available_power_w=35.0)
        )
        by_id = {a["id"]: a for a in result["allocations"]}
        self.assertAlmostEqual(by_id["a"]["allocated_power_w"], 15.0)
        self.assertAlmostEqual(by_id["b"]["allocated_power_w"], 20.0)
        self.assertEqual(by_id["a"]["state"], "limited")
        self.assertEqual(by_id["b"]["state"], "limited")

    def test_same_level_minimums_split_proportionally(self) -> None:
        # Level mins total 30 but only 15 available -> 1:2 split, lower shed.
        result = self.service.allocate_power_budget(
            base_request(
                available_power_w=15.0,
                loads=[
                    load("a", 50.0, 10.0, 10),
                    load("b", 50.0, 20.0, 10),
                    load("c", 10.0, 5.0, 1),
                ],
            )
        )
        by_id = {a["id"]: a for a in result["allocations"]}
        self.assertAlmostEqual(by_id["a"]["allocated_power_w"], 5.0)
        self.assertAlmostEqual(by_id["b"]["allocated_power_w"], 10.0)
        self.assertAlmostEqual(by_id["c"]["allocated_power_w"], 0.0)
        self.assertEqual(by_id["a"]["state"], "limited")
        self.assertEqual(by_id["b"]["state"], "limited")
        self.assertEqual(by_id["c"]["state"], "shed")
        self.assertAlmostEqual(result["allocated_power_w"], 15.0)

    def test_same_level_demand_topup_split_by_unmet_need(self) -> None:
        # mins 10 + 10 = 20 funded; 20 left for needs 40 (a) and 20 (b) -> 2:1.
        result = self.service.allocate_power_budget(
            base_request(
                available_power_w=40.0,
                loads=[
                    load("a", 50.0, 10.0, 10),
                    load("b", 30.0, 10.0, 10),
                ],
            )
        )
        by_id = {a["id"]: a for a in result["allocations"]}
        self.assertAlmostEqual(by_id["a"]["allocated_power_w"], 10.0 + 40.0 / 3.0)
        self.assertAlmostEqual(by_id["b"]["allocated_power_w"], 10.0 + 20.0 / 3.0)
        self.assertAlmostEqual(result["allocated_power_w"], 40.0)

    def test_zero_demand_is_powered(self) -> None:
        result = self.service.allocate_power_budget(
            base_request(
                available_power_w=5.0,
                loads=[load("z", 0.0, 0.0, 0), load("a", 50.0, 10.0, 10)],
            )
        )
        by_id = {a["id"]: a for a in result["allocations"]}
        self.assertEqual(by_id["z"]["state"], "powered")
        self.assertAlmostEqual(by_id["z"]["allocated_power_w"], 0.0)
        self.assertEqual(by_id["a"]["state"], "limited")
        self.assertEqual(result["status"], "constrained")

    def test_shed_when_no_power(self) -> None:
        result = self.service.allocate_power_budget(
            base_request(available_power_w=0.0)
        )
        for item in result["allocations"]:
            self.assertEqual(item["state"], "shed")
            self.assertAlmostEqual(item["allocated_power_w"], 0.0)
        self.assertAlmostEqual(result["allocated_power_w"], 0.0)
        self.assertAlmostEqual(result["unallocated_power_w"], 0.0)
        self.assertEqual(result["status"], "constrained")

    def test_unallocated_leftover_when_demand_below_budget(self) -> None:
        result = self.service.allocate_power_budget(
            base_request(available_power_w=500.0, reserve_power_w=100.0)
        )
        self.assertEqual(result["status"], "satisfied")
        self.assertAlmostEqual(result["allocated_power_w"], 110.0)
        self.assertAlmostEqual(result["unallocated_power_w"], 290.0)

    def test_shuffling_loads_keeps_per_id_results(self) -> None:
        loads = [
            load("a", 50.0, 10.0, 10),
            load("b", 30.0, 10.0, 10),
            load("c", 20.0, 5.0, 20),
            load("d", 10.0, 0.0, 1),
        ]
        forward = self.service.allocate_power_budget(
            base_request(available_power_w=42.0, loads=loads)
        )
        backward = self.service.allocate_power_budget(
            base_request(available_power_w=42.0, loads=list(reversed(loads)))
        )
        forward_by_id = {a["id"]: a for a in forward["allocations"]}
        backward_by_id = {a["id"]: a for a in backward["allocations"]}
        self.assertEqual(forward_by_id, backward_by_id)
        self.assertEqual(
            [a["id"] for a in backward["allocations"]], ["d", "c", "b", "a"]
        )

    def test_call_does_not_modify_input(self) -> None:
        payload = base_request(available_power_w=42.0, reserve_power_w=2.0)
        snapshot = json.loads(json.dumps(payload))
        self.service.allocate_power_budget(payload)
        self.assertEqual(payload, snapshot)

    def test_allocations_never_exceed_demand_or_budget(self) -> None:
        result = self.service.allocate_power_budget(
            base_request(
                available_power_w=33.3,
                reserve_power_w=3.3,
                loads=[
                    load("a", 10.0, 3.0, 7),
                    load("b", 10.0, 3.0, 7),
                    load("c", 10.0, 3.0, 7),
                ],
            )
        )
        total = 0.0
        for item in result["allocations"]:
            self.assertGreaterEqual(item["allocated_power_w"], 0.0)
            self.assertLessEqual(item["allocated_power_w"], 10.0)
            total += item["allocated_power_w"]
        self.assertLessEqual(total, 30.0 + 1e-9)
        self.assertAlmostEqual(total, result["allocated_power_w"])


class PowerBudgetValidationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def assert_code(self, payload, code, status=422):
        with self.assertRaises(ApiError) as ctx:
            self.service.allocate_power_budget(payload)
        self.assertEqual(ctx.exception.code, code)
        self.assertEqual(ctx.exception.status, status)
        self.assertTrue(ctx.exception.message)

    def test_non_object_payload_is_invalid_json(self) -> None:
        for payload in (None, [], "text", 5, 1.5, True):
            self.assert_code(payload, "invalid_json", status=400)

    def test_available_power_rules(self) -> None:
        self.assert_code(base_request(available_power_w=None), "invalid_budget")
        self.assert_code(base_request(available_power_w=-1.0), "invalid_budget")
        self.assert_code(base_request(available_power_w=True), "invalid_budget")
        self.assert_code(base_request(available_power_w="x"), "invalid_budget")
        self.assert_code(
            base_request(available_power_w=float("nan")), "invalid_budget"
        )
        self.assert_code(
            base_request(available_power_w=float("inf")), "invalid_budget"
        )
        missing = {k: v for k, v in base_request().items() if k != "available_power_w"}
        self.assert_code(missing, "invalid_budget")

    def test_reserve_power_rules(self) -> None:
        self.assert_code(base_request(reserve_power_w=-0.5), "invalid_budget")
        self.assert_code(base_request(reserve_power_w=False), "invalid_budget")
        self.assert_code(base_request(reserve_power_w="x"), "invalid_budget")
        self.assert_code(
            base_request(reserve_power_w=float("nan")), "invalid_budget"
        )
        self.assert_code(
            base_request(available_power_w=10.0, reserve_power_w=10.5),
            "invalid_budget",
        )
        # Reserve equal to available is allowed.
        result = self.service.allocate_power_budget(
            base_request(available_power_w=10.0, reserve_power_w=10.0)
        )
        self.assertAlmostEqual(result["allocated_power_w"], 0.0)

    def test_loads_rules(self) -> None:
        self.assert_code(base_request(loads=[]), "invalid_loads")
        self.assert_code(base_request(loads=None), "invalid_loads")
        self.assert_code(base_request(loads="x"), "invalid_loads")
        self.assert_code(base_request(loads=[1, 2]), "invalid_loads")
        self.assert_code(base_request(loads=[None]), "invalid_loads")
        missing = {k: v for k, v in base_request().items() if k != "loads"}
        self.assert_code(missing, "invalid_loads")

    def test_load_id_rules(self) -> None:
        self.assert_code(
            base_request(loads=[load("", 1.0, 0.0, 1)]), "invalid_load_id"
        )
        self.assert_code(
            base_request(loads=[load(None, 1.0, 0.0, 1)]), "invalid_load_id"
        )
        self.assert_code(
            base_request(loads=[load(7, 1.0, 0.0, 1)]), "invalid_load_id"
        )
        no_id = {"demand_power_w": 1.0, "min_power_w": 0.0, "priority": 1}
        self.assert_code(base_request(loads=[no_id]), "invalid_load_id")
        self.assert_code(
            base_request(loads=[load("a", 1.0, 0.0, 1), load("a", 2.0, 0.0, 2)]),
            "invalid_load_id",
        )

    def test_load_power_rules(self) -> None:
        def with_load(**fields):
            entry = load("a", 1.0, 0.0, 1)
            entry.update(fields)
            return base_request(loads=[entry])

        for bad in (None, -1.0, True, "x", float("nan"), float("inf")):
            self.assert_code(
                with_load(demand_power_w=bad), "invalid_load_power"
            )
            self.assert_code(
                with_load(demand_power_w=5.0, min_power_w=bad),
                "invalid_load_power",
            )
        self.assert_code(
            with_load(demand_power_w=5.0, min_power_w=5.5), "invalid_load_power"
        )
        for key in ("demand_power_w", "min_power_w"):
            entry = load("a", 1.0, 0.0, 1)
            del entry[key]
            self.assert_code(base_request(loads=[entry]), "invalid_load_power")
        # min equal to demand is allowed.
        result = self.service.allocate_power_budget(
            base_request(loads=[load("a", 5.0, 5.0, 1)])
        )
        self.assertEqual(result["allocations"][0]["state"], "powered")

    def test_priority_rules(self) -> None:
        def with_priority(priority):
            return base_request(loads=[load("a", 1.0, 0.0, priority)])

        for bad in (None, True, False, 1.5, "3", -1, 101, float("nan")):
            self.assert_code(with_priority(bad), "invalid_priority")
        entry = load("a", 1.0, 0.0, 1)
        del entry["priority"]
        self.assert_code(base_request(loads=[entry]), "invalid_priority")
        # Boundary values are allowed.
        for ok in (0, 100):
            result = self.service.allocate_power_budget(with_priority(ok))
            self.assertEqual(result["status"], "satisfied")


class PowerBudgetHttpTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.httpd = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()
        cls.base = f"http://127.0.0.1:{cls.httpd.server_address[1]}"

    @classmethod
    def tearDownClass(cls) -> None:
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join(timeout=5)

    def post(self, route, raw):
        request = urllib.request.Request(
            self.base + route,
            data=raw,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request) as response:
                return response.status, json.loads(response.read())
        except urllib.error.HTTPError as exc:
            body = json.loads(exc.read())
            exc.close()
            return exc.code, body

    def test_allocate_route_returns_200(self) -> None:
        status, body = self.post(POWER_BUDGET_ROUTE, json.dumps(base_request()).encode())
        self.assertEqual(status, 200)
        self.assertEqual(body["status"], "satisfied")
        self.assertEqual(len(body["allocations"]), 2)

    def test_missing_body_is_invalid_json(self) -> None:
        status, body = self.post(POWER_BUDGET_ROUTE, b"")
        self.assertEqual(status, 400)
        self.assertEqual(body["error"]["code"], "invalid_json")

    def test_malformed_json_is_invalid_json(self) -> None:
        status, body = self.post(POWER_BUDGET_ROUTE, b"{oops")
        self.assertEqual(status, 400)
        self.assertEqual(body["error"]["code"], "invalid_json")

    def test_json_array_is_invalid_json(self) -> None:
        status, body = self.post(POWER_BUDGET_ROUTE, b"[1]")
        self.assertEqual(status, 400)
        self.assertEqual(body["error"]["code"], "invalid_json")

    def test_invalid_budget_is_422(self) -> None:
        payload = base_request(available_power_w=-1.0)
        status, body = self.post(POWER_BUDGET_ROUTE, json.dumps(payload).encode())
        self.assertEqual(status, 422)
        self.assertEqual(body["error"]["code"], "invalid_budget")
        self.assertTrue(body["error"]["message"])

    def test_invalid_priority_is_422(self) -> None:
        payload = base_request(loads=[load("a", 1.0, 0.0, 101)])
        status, body = self.post(POWER_BUDGET_ROUTE, json.dumps(payload).encode())
        self.assertEqual(status, 422)
        self.assertEqual(body["error"]["code"], "invalid_priority")

    def test_unknown_post_path_is_still_404(self) -> None:
        status, body = self.post("/v1/power/unknown", b"{}")
        self.assertEqual(status, 404)
        self.assertEqual(body["error"]["code"], "not_found")


